/*************************************************
* Name:        ntt
*
* Description: Inplace number-theoretic transform (NTT) in Rq.
*              input is in standard order, output is in bitreversed order
*
* Arguments:   - int16_t r[256]: pointer to input/output vector of elements of Zq
**************************************************/
void kyber_ntt(int16x8_t r[SMAUGT_N_VEC]) {
    KYBER_AARCH64__asm_ntt_SIMD_top(r, kyber_streamlined_CT_negacyclic_table_jump_extended, kyber_constants);
    KYBER_AARCH64__asm_ntt_SIMD_bot(r, kyber_streamlined_CT_negacyclic_table_jump_extended, kyber_constants);
}


/*************************************************
* Name:        invntt_tomont
*
* Description: Inplace inverse number-theoretic transform in Rq and
*              multiplication by Montgomery factor 2^16.
*              Input is in bitreversed order, output is in standard order
*
* Arguments:   - int16_t r[256] in {-(q-1)/2,...,(q-1)/2}
*              pointer to input/output vector of elements of Zq
**************************************************/
void kyber_invntt(int16x8_t r[SMAUGT_N_VEC]) {
    KYBER_AARCH64__asm_intt_SIMD_bot(r, kyber_streamlined_inv_GS_negacyclic_table_jump_extended, kyber_constants); 
    KYBER_AARCH64__asm_intt_SIMD_top(r, kyber_streamlined_inv_GS_negacyclic_table_jump_extended, kyber_constants); 
}


void kyber_base_mul_montgomery(int16x8_t *polyout, int16x8_t *poly1, int16x8_t *poly2) {
    int16x8_t poly2_asymmetric[SMAUGT_N_VEC>>1] = {0};
    
    KYBER_AARCH64__asm_point_mul_extended(poly2_asymmetric, poly2, kyber_pre_asymmetric_table_extended, kyber_asymmetric_const);
    
    KYBER_AARCH64__asm_poly_base_mul_mont(polyout, poly1, poly2, poly2_asymmetric, kyber_asymmetric_const);
}


void kyber_mv(int16x8_t acc[SMAUGT_K][SMAUGT_N_VEC], int16x8_t s[SMAUGT_K][SMAUGT_N_VEC], int16x8_t s_asymmetric[SMAUGT_K][SMAUGT_N_VEC>>1],  int16x8_t A[SMAUGT_K][SMAUGT_K][SMAUGT_N_VEC]){ 
    for (size_t j = 0; j < SMAUGT_K; j++){
        kyber_ntt(&(s[j][0]));
        KYBER_AARCH64__asm_point_mul_extended(&(s_asymmetric[j][0]), &(s[j][0]), kyber_pre_asymmetric_table_extended, kyber_asymmetric_const);
    }

    for (size_t i = 0; i < SMAUGT_K; i++) {
        for (size_t j = 0; j < SMAUGT_K; j++) {
            kyber_ntt(&(A[i][j][0]));
        }
    }

    for (size_t j = 0; j < SMAUGT_K; j++){
        KYBER_AARCH64__asm_asymmetric_mul(&(acc[j][0]), &(A[j][0][0]), &(s[0][0]), &(s_asymmetric[0][0]), kyber_asymmetric_const);
        //KYBER_AARCH64__asm_asymmetric_mul_montgomery(&(acc[j][0]), &(A[j][0][0]), &(s[0][0]), &(s_asymmetric[0][0]), kyber_asymmetric_const);
    }
    
    for (size_t j = 0; j < SMAUGT_K; j++){
        kyber_invntt(&(acc[j][0]));
    }    
    
}


void kyber_vv(int16x8_t acc[SMAUGT_N_VEC], int16x8_t s[SMAUGT_K][SMAUGT_N_VEC], int16x8_t s_asymmetric[SMAUGT_K][SMAUGT_N_VEC>>1],  int16x8_t A[SMAUGT_K][SMAUGT_N_VEC]){ 
    for (size_t j = 0; j < SMAUGT_K; j++){
        kyber_ntt(&(s[j][0]));
        KYBER_AARCH64__asm_point_mul_extended(&(s_asymmetric[j][0]), &(s[j][0]), kyber_pre_asymmetric_table_extended, kyber_asymmetric_const);
    }

    for (size_t i = 0; i < SMAUGT_K; i++) kyber_ntt(&(A[i][0]));

    KYBER_AARCH64__asm_asymmetric_mul(&(acc[0]), &(A[0][0]), &(s[0][0]), &(s_asymmetric[0][0]), kyber_asymmetric_const);
    kyber_invntt(&(acc[0]));
}